const { chromium } = require('./viewer-api/viewer-api/frontend/dioxus/node_modules/@playwright/test');
const executablePath = 'C:/Users/linus/AppData/Local/ms-playwright/chromium-1223/chrome-win64/chrome.exe';
(async () => {
  const browser = await chromium.launch({ headless: false, executablePath });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  for (const [name, url, ready] of [
    ['ticket', 'http://127.0.0.1:3002', 'header.header'],
    ['spec', 'http://127.0.0.1:4002', 'header.header'],
    ['doc', 'http://127.0.0.1:3001', '.app'],
  ]) {
    await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 120000 });
    await page.locator(ready).first().waitFor({ state: 'visible', timeout: 60000 });
    const candidates = await page.locator('h1,h2,h3,a,button,[role="treeitem"],[role="navigation"]').evaluateAll(nodes => nodes.filter(node => {
      const style = getComputedStyle(node);
      return style.visibility !== 'hidden' && style.display !== 'none' && node.textContent.trim();
    }).slice(0, 30).map(node => `${node.tagName}.${node.className}: ${node.textContent.trim().replace(/\s+/g, ' ').slice(0, 120)}`));
    console.log(`--- ${name} ---\n${candidates.join('\n')}`);
  }
  await browser.close();
})().catch(error => { console.error(error); process.exit(1); });
NODE

