const { chromium } = require('./viewer-api/viewer-api/frontend/dioxus/node_modules/@playwright/test');
const fs = require('node:fs');
const executablePath = 'C:/Users/linus/AppData/Local/ms-playwright/chromium-1223/chrome-win64/chrome.exe';
const evidenceDir = 'target/browser-evidence';
const checks = [
  { name: 'ticket-viewer', url: 'http://127.0.0.1:3002', selector: 'button:has-text("+ New")', detail: 'visible + New ticket control' },
  { name: 'spec-viewer', url: 'http://127.0.0.1:4002', selector: 'h2.spec-tree-page__title:has-text("Specifications")', detail: 'visible Specifications heading' },
  { name: 'doc-viewer', url: 'http://127.0.0.1:3001', selector: '.tree-item-row:has-text("doc-viewer")', detail: 'visible doc-viewer navigation row' },
];
(async () => {
  const browser = await chromium.launch({ headless: false, executablePath });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const consoleErrors = [];
  const failedRequests = [];
  page.on('console', msg => { if (msg.type() === 'error') consoleErrors.push(msg.text()); });
  page.on('requestfailed', request => failedRequests.push(`${request.method()} ${request.url()} ${request.failure()?.errorText ?? ''}`));
  page.on('response', response => { if (response.status() >= 400) failedRequests.push(`${response.status()} ${response.url()}`); });
  for (const check of checks) {
    await page.goto(check.url, { waitUntil: 'domcontentloaded', timeout: 120000 });
    await page.locator(check.selector).first().waitFor({ state: 'visible', timeout: 60000 });
    await page.screenshot({ path: `${evidenceDir}/${check.name}-after-seam-fix-1440x900.png`, fullPage: true });
    console.log(`${check.name}: ${check.detail}`);
  }
  await browser.close();
  if (consoleErrors.length || failedRequests.length) {
    console.error(JSON.stringify({ consoleErrors, failedRequests }, null, 2));
    process.exit(1);
  }
  console.log('browser-errors: none');
})().catch(error => { console.error(error); process.exit(1); });
